import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CHeM0PsO.js";const i="/images/agent-memory-semantic.webp",l="/images/agent-memory-notes.webp",_=JSON.parse('{"title":"记忆","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/memory.md","filePath":"guide/agent/memory.md","lastUpdated":1789295632000}'),n={name:"guide/agent/memory.md"};function s(g,t,m,p,d,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="记忆" tabindex="-1">记忆 <a class="header-anchor" href="#记忆" aria-label="Permalink to &quot;记忆&quot;">​</a></h1><p>对话越长，最早的消息就越容易超出模型的上下文窗口（界面上表现为出现<a href="/guide/agent/chat#消息">上下文边界</a>）。记忆功能让角色在窗口之外也能「记住」之前的内容。</p><p>记忆按<strong>单个会话</strong>独立开启，每个会话在「记忆」标签页选择方式。两种方式可以都试试，看哪种更合用。</p><h2 id="方式一-语义记忆-云端" tabindex="-1">方式一：语义记忆（云端） <a class="header-anchor" href="#方式一-语义记忆-云端" aria-label="Permalink to &quot;方式一：语义记忆（云端）&quot;">​</a></h2><p>由云端记忆服务（阿里云百炼）自动从对话中提炼要点，之后每轮发送前按语义检索相关内容注入给角色，使用过程几乎无感。</p><p>可调参数：</p><ul><li><strong>是否启用本会话的记忆</strong></li><li><strong>检索条数</strong>：每次发消息前最多召回几条记忆</li><li><strong>注入上下文的最大字符数</strong>：防止记忆占用过多窗口</li><li><strong>写入记忆的对话轮数与频率</strong>：多久提炼一次</li><li><strong>最低相关度</strong>：过滤不够相关的记忆</li></ul><p>「记忆节点」管理界面可以查看已保存的记忆条目，手动<strong>添加、编辑、删除</strong>——觉得角色记错了什么，直接改。</p><p><img src="'+i+'" alt="语义记忆"></p><h2 id="方式二-压缩便签" tabindex="-1">方式二：压缩便签 <a class="header-anchor" href="#方式二-压缩便签" aria-label="Permalink to &quot;方式二：压缩便签&quot;">​</a></h2><p>由 AI 模型把较早的对话压缩成一条条「便签」摘要。当对话超出上下文窗口时，角色通过便笔回顾之前的内容。相比语义记忆，便签更透明——你能看到、能改每一份摘要。</p><ul><li>每条便签覆盖一段对话区间，可以点开查看起止消息并跳转定位。</li><li>便签支持<strong>手动编辑、调整顺序、删除</strong>。删除后，对应区间的消息会重新以原文进入对话历史。</li><li>便签有状态：生成中 / 参与回复 / 休眠中 / 失败。失败的便签可以重试，也可以自己手写摘要填进去。</li><li>「记忆」页提供消息分段总览：自上而下由新到旧，能直观看到哪些消息在窗口内、哪些在排队、哪些已被总结。</li><li>可以为会话单独选择<strong>压缩模型</strong>，便签摘要按所选模型<strong>单独计费</strong>（扣费时机可能与当轮回复略有先后）。</li><li>切换压缩模型会<strong>清空当前会话的已有便签</strong>（缓存失效），需要重新压缩。</li></ul><p><img src="'+l+'" alt="便签压缩"></p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>两种记忆都随会话隔离：A 会话的记忆不会进入 B 会话。</li><li><strong>删除会话</strong>时会同时删除该会话的便签和云端记忆条目，且不可恢复；如需保留，先导出聊天记录。</li><li>记忆不是完美复刻：语义记忆是提炼，便签是摘要。关键细节建议写进<a href="/guide/agent/worldbook">世界书</a>（创作者侧）或重要剧情节点手动补一条记忆节点。</li></ul>',15)])])}const u=a(n,[["render",s]]);export{_ as __pageData,u as default};
